motion:
/* hook: a slow push on you, curled in the back seat */
tl.fromTo("#hookfig", { scale: 1.0, transformOrigin: "50% 60%" }, { scale: 1.07, duration: 6.0, ease: "none" }, 2.4);
/* wide: the level drifts, the big 4 draws itself on */
tl.fromTo("#levelart", { scale: 1.00 }, { scale: 1.10, duration: 4.4, ease: "none" }, 9.0);
tl.fromTo("#bigfour", { drawSVG: "0% 0%" }, { drawSVG: "0% 100%", duration: 1.6, ease: "power1.inOut" }, 9.2);
/* rule 1 obeyed: the arrow from your car to the ramp draws on as you "do" it */
tl.fromTo("#nosearrow", { drawSVG: "0% 0%" }, { drawSVG: "0% 100%", duration: 0.9, ease: "power2.out" }, 17.2);
tl.fromTo("#nosehead",  { drawSVG: "0% 0%" }, { drawSVG: "0% 100%", duration: 0.35, ease: "power2.out" }, 18.0);
/* plant: three facts, each landing on its word */
tl.fromTo("#plant1", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 20.9);
tl.fromTo("#plant2", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 21.9);
tl.fromTo("#plant3", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 23.1);
/* rule 2 obeyed: from the back seat, the far door catches a little light */
tl.fromTo("#fardoor", { boxShadow: "0 0 0 0 rgba(190,215,255,0)" }, { boxShadow: "0 0 30px 6px rgba(190,215,255,.25)", duration: 2.4, ease: "sine.inOut" }, 30.6);
/* radio: the line resolves out of static */
tl.fromTo("#radiobox", { scale: 0.98 }, { scale: 1.04, duration: 4.8, ease: "none" }, 34.2);
tl.set("#radioline", { textContent: "" }, 34.2);
tl.to("#radioline", { duration: 1.3, scrambleText: { text: "STAY ABOVE STREET LEVEL", chars: "upperCase", speed: 0.6 } }, 36.4);
/* rule 3 obeyed: the map settles */
tl.fromTo("#maparea", { scale: 1.03 }, { scale: 1.0, duration: 3.4, ease: "power1.out" }, 43.1);
/* door: a wedge of stairwell light opens, then is let close softly */
tl.fromTo("#wedge", { width: 0 }, { width: 190, duration: 1.5, ease: "power2.out" }, 52.6);
tl.to("#wedge", { width: 0, duration: 2.6, ease: "power1.inOut" }, 56.6);
/* footsteps: the pools light one at a time and a shadow crosses them */
[60.35, 61.15, 61.95].forEach((t, i) => {
  tl.fromTo(`#pool${i + 1}`, { opacity: 0.13 }, { opacity: 0.46, duration: 0.2, yoyo: true, repeat: 1 }, t);
});
tl.fromTo("#shadow", { x: 0 }, { x: 560, duration: 2.6, ease: "none" }, 60.15);
/* the voice: it knows a thing nobody was told */
tl.fromTo("#halo", { opacity: 0.3 }, { opacity: 0.85, duration: 3.0, ease: "sine.inOut" }, 63.6);
tl.to("#lvl", { duration: 1.1, scrambleText: { text: "LEVEL 4", chars: "0123456789", speed: 0.8, revealDelay: 0.35 } }, 63.7);
/* recall: the stamp */
tl.fromTo("#brakestamp", { scale: 1.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.32, ease: "power3.out" }, 71.1);
/* THE PAYOFF: a car appears in the bay that was empty; the count fails over; the camera pushes in */
tl.fromTo("#car13b", { opacity: 0, scale: 0.6 }, { opacity: 1, scale: 1, duration: 0.4, ease: "power3.out" }, 75.95);
tl.to("#car13b", { boxShadow: "0 0 0 14px rgba(255,66,66,.0)", duration: 1.2, ease: "power2.out", repeat: 1 }, 76.25);
tl.to("#mapcount2", { duration: 0.85, scrambleText: { text: "13", chars: "0123456789", speed: 0.7, revealDelay: 0.3 } }, 75.85);
tl.fromTo("#mapcount2", { color: "#ffffff", scale: 1 }, { color: "#ff4242", scale: 1.25, duration: 0.4, ease: "power3.out" }, 76.35);
tl.fromTo("#maparea2", { scale: 1.0 }, { scale: 1.14, duration: 2.4, ease: "power1.in" }, 75.95);
